1992			return -ENOMEM;
1993		}
1994	
1995		session->br_chan.chan.conn = conn;
1996		bt_avdtp_clear_tx(session);
1997		k_sem_give(&avdtp_sem_lock);
1998	
1999		/* Locking semaphore initialized to 1 (unlocked) */
2000		k_sem_init(&session->sem_lock, 1, 1);
2001		k_work_init(&session->_release_work, avdtp_release_work);
2002		session->br_chan.rx.mtu = BT_L2CAP_RX_MTU;
2003		session->br_chan.chan.ops = &signal_chan_ops;
2004		session->br_chan.required_sec_level = BT_SECURITY_L2;
